  const raw = allDiffs(a, b);
  if (!raw.diffs.length) return { cls: 'same', diffs: [] };
  if (!raw.structural) { const tags = benignTags(raw.diffs); if (tags) return { cls: tagsCls(tags), diffs: raw.diffs }; }
