    // frame. Replaced here with: call original function once per frame, computing target timestamp
    // directly from frame number (same formula as `bakeFrame` to compute target timestamp); with a very
    // large step size, original function advances exactly one frame each time, landing on this
    // timestamp. As before, yields a macrotask between frames.
    const clock = window.__pcStageClock;
